a.label('pg_clk_on_ev');    a.u32(0x08029349)   # Verified ClockGenerator::onEvent!
a.label('pg_memset');       a.u32(0x0802D1A3)
a.label('pg_max_dt_us');    a.u32(50000)
a.label('pg_min_cbpm');     a.u32(2000)
a.label('pg_def_cbpm');     a.u32(12000)
a.label('pg_max_cbpm');     a.u32(30000)
a.label('pg_f8_thresh');    a.u32(250000000)
a.label('pg_t_transp');     a.u32('str_t_transport')
a.label('pg_v_play');       a.u32('str_v_play')
a.label('pg_v_stop_clk');   a.u32('str_v_stop_clk')
a.label('pg_v_stop_free');  a.u32('str_v_stop_free')

# ==============================================================================
# ISLAND H1: Dawless Riser & Drop Core (Multi-HW Tension, Snap-Back, Drop, Bank B LEDs)
# ==============================================================================

# Helper: otf_send_midi3 (r0 = status, r1 = data1, r2 = data2)
a.label('otf_send_midi3')
a.emit(push([4], lr=True))
a.emit(sub_sp(8))
a.emit(add_r_sp(3, 0))
a.emit(strb_imm(0, 3, 0))
a.emit(strb_imm(1, 3, 1))
a.emit(strb_imm(2, 3, 2))
a.emit(movs_reg(1, 3))
a.ldr_lit(3, 'ph1_midi_send3')
a.emit(blx(3))
a.emit(add_sp(8))
a.emit(pop([4], pc=True))

# Helper: otf_get_active_ch -> returns r0 = 0..15
a.label('otf_get_active_ch')
a.emit(push([4], lr=True))
a.emit(movs_imm(0, 0x0D))
a.emit(movs_imm(1, 0))
a.ldr_lit(3, 'ph1_get_ch')
a.emit(blx(3))
a.emit(movs_imm(1, 0x0F))
a.emit(ands_reg(0, 1))
a.emit(pop([4], pc=True))

# Helper: otf_fire_d1_roll_hit (r0 = velocity 1..127) -> Ch 10 SD (38) + HC (39 if vel >= 100)
a.label('otf_fire_d1_roll_hit')
a.emit(push([4, 5], lr=True))
a.emit(movs_reg(4, 0))
a.ldr_lit(5, 'ph1_riser')
a.emit(movs_imm(0, 0x99))      # Ch 10 Note On
a.emit(movs_imm(1, 38))        # Donner D1 SD (Snare)
a.emit(movs_reg(2, 4))
a.bl('otf_send_midi3')
a.emit(cmp_imm(4, 100))
a.b_cond('lo', 'h1_roll_set_on')
a.emit(movs_imm(0, 0x99))
a.emit(movs_imm(1, 39))        # Donner D1 HC (Hand Clap)
a.emit(movs_reg(2, 4))
a.emit(subs_imm8(2, 8))
a.bl('otf_send_midi3')
a.label('h1_roll_set_on')
a.emit(movs_imm(1, 1))
a.emit(strb_imm(1, 5, RS_ROLL_NOTE_ON))
a.emit(pop([4, 5], pc=True))

# Helper: otf_apply_riser_tension (r0 = tension 0..127)
# Sweeps SH-4d Ch 1-4 Cutoff (CC74 -> 127) & Reverb (CC91 -> 110) + RC-505 Ch 14 Input FX (CC80/81)
a.label('otf_apply_riser_tension')
a.emit(push([4, 5, 6, 7], lr=True))
a.emit(movs_reg(5, 0))
a.emit(movs_imm(1, 0x7F))
a.emit(ands_reg(5, 1))         # r5 = 0..127
a.ldr_lit(4, 'ph1_riser')
a.emit(ldrb_imm(1, 4, RS_LAST_TENSION))
a.emit(cmp_reg(5, 1))
a.b_cond('eq', 'h1_ten_done')
a.emit(strb_imm(5, 4, RS_LAST_TENSION))

a.emit(movs_reg(6, 5))         # r6 = scale 0..128
a.emit(cmp_imm(6, 0))
a.b_cond('eq', 'h1_ten_rc80_off')
a.emit(adds_imm8(6, 1))        # 1..128 so tension=127 reaches exact 100% target
a.emit(ldrb_imm(1, 4, RS_RC80_ON))
a.emit(cmp_imm(1, 0))
a.b_cond('ne', 'h1_ten_rc81')
a.emit(movs_imm(1, 1))
a.emit(strb_imm(1, 4, RS_RC80_ON))
a.emit(movs_imm(0, 0xBD))      # Ch 14 CC
a.emit(movs_imm(1, 80))        # RC-505 INPUT FX ON
a.emit(movs_imm(2, 127))
a.bl('otf_send_midi3')
a.b('h1_ten_rc81')

a.label('h1_ten_rc80_off')
a.emit(ldrb_imm(1, 4, RS_RC80_ON))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h1_ten_rc81')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 4, RS_RC80_ON))
a.emit(movs_imm(0, 0xBD))
a.emit(movs_imm(1, 80))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')

a.label('h1_ten_rc81')
a.emit(ldrb_imm(1, 4, RS_HOME_RC81))
a.emit(movs_imm(2, 127))
a.emit(subs_reg(2, 2, 1))
a.emit(muls_reg(2, 6))
a.emit(asrs_imm(2, 2, 7))
a.emit(adds_reg(2, 1, 2))
a.emit(movs_imm(0, 0xBD))
a.emit(movs_imm(1, 81))        # RC-505 INPUT FX CONTROL
a.bl('otf_send_midi3')

a.emit(movs_imm(7, 0))         # ch = 0..3 (Roland SH-4d Parts 1-4)
a.label('h1_ten_sh4d_loop')
a.emit(ldrb_reg(1, 4, 7))      # RS_HOME_CUT[ch]
a.emit(movs_imm(2, 127))
a.emit(subs_reg(2, 2, 1))
a.emit(muls_reg(2, 6))
a.emit(asrs_imm(2, 2, 7))
a.emit(adds_reg(2, 1, 2))
a.emit(movs_imm(0, 0xB0))
a.emit(adds_reg(0, 0, 7))
a.emit(movs_imm(1, 74))        # Cutoff (CC74)
a.bl('otf_send_midi3')

a.emit(adds_imm3(3, 7, RS_HOME_REV))
a.emit(ldrb_reg(1, 4, 3))      # RS_HOME_REV[ch]
a.emit(movs_imm(2, 110))
a.emit(subs_reg(2, 2, 1))
a.emit(muls_reg(2, 6))
a.emit(asrs_imm(2, 2, 7))
a.emit(adds_reg(2, 1, 2))
a.emit(movs_imm(0, 0xB0))
a.emit(adds_reg(0, 0, 7))
a.emit(movs_imm(1, 91))        # Reverb (CC91)
a.bl('otf_send_midi3')

a.emit(adds_imm8(7, 1))
a.emit(cmp_imm(7, 4))
a.b_cond('lo', 'h1_ten_sh4d_loop')

a.label('h1_ten_done')
a.emit(pop([4, 5, 6, 7], pc=True))

# Helper: otf_restore_original_ccs -> Instant <1ms Snap-Back to user's Original Values!
a.label('otf_restore_original_ccs')
a.emit(push([4, 5, 6], lr=True))
a.ldr_lit(4, 'ph1_riser')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 4, RS_AUTORISER))
a.emit(strb_imm(1, 4, RS_MANUAL_RISER))
a.emit(strb_imm(1, 4, RS_VACUUM_HELD))
a.emit(strb_imm(1, 4, RS_ROLL_HELD))
a.emit(strb_imm(1, 4, RS_RC80_ON))
a.emit(movs_imm(2, 0xFF))
a.emit(strb_imm(2, 4, RS_LAST_TENSION))

a.emit(ldrb_imm(2, 4, RS_ROLL_NOTE_ON))
a.emit(cmp_imm(2, 0))
a.b_cond('eq', 'h1_rst_chk_pb')
a.emit(strb_imm(1, 4, RS_ROLL_NOTE_ON))
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 38))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 39))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')

a.label('h1_rst_chk_pb')
a.emit(ldrb_imm(2, 4, RS_PITCH_MODE))
a.emit(cmp_imm(2, 0))
a.b_cond('eq', 'h1_rst_act_pb')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 4, RS_PITCH_MODE))
a.emit(ldrb_imm(5, 4, RS_PITCH_CH))
a.emit(movs_imm(0, 0xE0))
a.emit(orrs_reg(0, 5))
a.emit(movs_imm(1, 0))
a.emit(movs_imm(2, 0x40))      # Center Pitch Bend = 0
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0xB0))
a.emit(orrs_reg(0, 5))
a.emit(movs_imm(1, 1))
a.emit(ldrb_imm(2, 4, RS_HOME_MOD))
a.bl('otf_send_midi3')

a.label('h1_rst_act_pb')
a.bl('otf_get_active_ch')
a.emit(movs_reg(5, 0))
a.emit(movs_imm(0, 0xE0))
a.emit(orrs_reg(0, 5))
a.emit(movs_imm(1, 0))
a.emit(movs_imm(2, 0x40))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0xB0))
a.emit(orrs_reg(0, 5))
a.emit(movs_imm(1, 1))
a.emit(ldrb_imm(2, 4, RS_HOME_MOD))
a.bl('otf_send_midi3')

# Restore RC-505mkII Ch 14 Input FX Control & OFF
a.emit(movs_imm(0, 0xBD))
a.emit(movs_imm(1, 81))
a.emit(ldrb_imm(2, 4, RS_HOME_RC81))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0xBD))
a.emit(movs_imm(1, 80))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')

# Restore SH-4d Ch 1-4 Original Cutoff (CC74) & Reverb (CC91)
a.emit(movs_imm(6, 0))
a.label('h1_rst_sh4d_loop')
a.emit(movs_imm(0, 0xB0))
a.emit(adds_reg(0, 0, 6))
a.emit(movs_imm(1, 74))
a.emit(ldrb_reg(2, 4, 6))
a.bl('otf_send_midi3')

a.emit(movs_imm(0, 0xB0))
a.emit(adds_reg(0, 0, 6))
a.emit(movs_imm(1, 91))
a.emit(adds_imm3(3, 6, RS_HOME_REV))
a.emit(ldrb_reg(2, 4, 3))
a.bl('otf_send_midi3')

a.emit(adds_imm8(6, 1))
a.emit(cmp_imm(6, 4))
a.b_cond('lo', 'h1_rst_sh4d_loop')
a.emit(pop([4, 5, 6], pc=True))

# Helper: otf_execute_drop -> Snap-Back + Step 1 Sync + Donner D1 Crash (49) & SMP2 Impact (62)!
a.label('otf_execute_drop')
a.emit(push([4, 5], lr=True))
a.bl('otf_restore_original_ccs')
a.bl('otf_reset_chain_to_start')
a.bl('otf_riser_sync_start')

a.ldr_lit(4, 'ph1_state')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 4, ST_PLAY_POS))
a.emit(strb_imm(1, 4, ST_ACTIVE_STEP))
a.ldr_lit(2, 'ph1_arp_handler')
a.emit(movs_imm(3, 0x8D))
a.emit(lsls_imm(3, 3, 1))
a.emit(movs_imm(1, 1))
a.emit(strb_reg(1, 2, 3))

# Fire Donner D1 Crash Cymbal (Note 49) + SMP2 Impact/Sub-Drop (Note 62) on Ch 10!
a.emit(movs_imm(0, 0x99))
a.emit(movs_imm(1, 49))
a.emit(movs_imm(2, 124))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0x99))
a.emit(movs_imm(1, 62))
a.emit(movs_imm(2, 126))
a.bl('otf_send_midi3')

a.ldr_lit(5, 'ph1_riser')
a.emit(movs_imm(1, 6))
a.emit(strb_imm(1, 5, RS_DROP_OFF_CNT))
a.emit(movs_imm(1, 24))
a.emit(strb_imm(1, 5, RS_DROP_FLASH))

a.bl('otf_refresh_pads')
a.ldr_lit(0, 'ph1_t_drop')
a.ldr_lit(1, 'ph1_v_drop')
a.bl('otf_show_param')
a.emit(pop([4, 5], pc=True))

# Helper: otf_compute_bank_b_rgb (r0 = pad_idx 0..7, r1 = out_rgb_ptr)
a.label('otf_compute_bank_b_rgb')
a.emit(push([4, 5], lr=True))
a.emit(movs_reg(4, 0))
a.emit(movs_reg(5, 1))
a.ldr_lit(3, 'ph1_riser')

# Pads 5 & 6 -> Master Transport Red / Green
a.emit(cmp_imm(4, 4))
a.b_cond('eq', 'h1_led_tr')
a.emit(cmp_imm(4, 5))
a.b_cond('ne', 'h1_led_chk0')
a.label('h1_led_tr')
a.bl('otf_compute_transport_rgb')
a.emit(pop([4, 5], pc=True))

a.label('h1_led_chk0')
a.emit(cmp_imm(4, 0))          # Pad 1: Accelerating Drum Roll (Cyan / White Strobe)
a.b_cond('ne', 'h1_led_chk1')
a.emit(ldrb_imm(1, 3, RS_ROLL_HELD))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h1_led_p0_idle')
a.emit(ldrb_imm(1, 3, RS_ROLL_NOTE_ON))
a.emit(cmp_imm(1, 0))
a.b_cond('ne', 'h1_led_white')
a.label('h1_led_p0_idle')
a.emit(movs_imm(0, 0))
a.emit(movs_imm(1, 72))
a.emit(movs_imm(2, 110))
a.b('h1_led_store')

a.label('h1_led_chk1')
a.emit(cmp_imm(4, 1))          # Pad 2: 4/8-Bar Auto-Riser (Warm Amber / Pulsing Gold)
a.b_cond('ne', 'h1_led_chk2')
a.emit(ldrb_imm(1, 3, RS_AUTORISER))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h1_led_p1_idle')
a.emit(ldrb_imm(1, 3, RS_BEAT_BLINK))
a.emit(cmp_imm(1, 6))
a.b_cond('hs', 'h1_led_p1_act')
a.emit(movs_imm(0, 126))
a.emit(movs_imm(1, 118))
a.emit(movs_imm(2, 50))
a.b('h1_led_store')
a.label('h1_led_p1_act')
a.emit(movs_imm(0, 124))
a.emit(movs_imm(1, 70))
a.emit(movs_imm(2, 0))
a.b('h1_led_store')
a.label('h1_led_p1_idle')
a.emit(movs_imm(0, 70))
a.emit(movs_imm(1, 28))
a.emit(movs_imm(2, 0))
a.b('h1_led_store')

a.label('h1_led_chk2')
a.emit(cmp_imm(4, 2))          # Pad 3: Synth Pitch Rise / Tape-Stop (Violet / Sky)
a.b_cond('ne', 'h1_led_chk3')
a.emit(ldrb_imm(1, 3, RS_PITCH_MODE))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h1_led_p2_idle')
a.emit(movs_imm(0, 70))
a.emit(movs_imm(1, 115))
a.emit(movs_imm(2, 126))
a.b('h1_led_store')
a.label('h1_led_p2_idle')
a.emit(movs_imm(0, 56))
a.emit(movs_imm(1, 0))
a.emit(movs_imm(2, 105))
a.b('h1_led_store')

a.label('h1_led_chk3')
a.emit(cmp_imm(4, 3))          # Pad 4: Pre-Drop Vacuum Gate (Magenta)
a.b_cond('ne', 'h1_led_chk6')
a.emit(ldrb_imm(1, 3, RS_VACUUM_HELD))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h1_led_p3_idle')
a.emit(movs_imm(0, 126))
a.emit(movs_imm(1, 36))
a.emit(movs_imm(2, 120))
a.b('h1_led_store')
a.label('h1_led_p3_idle')
a.emit(movs_imm(0, 78))
a.emit(movs_imm(1, 0))
a.emit(movs_imm(2, 48))
a.b('h1_led_store')

a.label('h1_led_chk6')
a.emit(cmp_imm(4, 6))          # Pad 7: D1 SMP1 Uplifter (Gold-Yellow)
a.b_cond('ne', 'h1_led_pad8')
a.emit(ldrb_imm(1, 3, RS_D1_FX_NOTE))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h1_led_p6_idle')
a.emit(movs_imm(0, 126))
a.emit(movs_imm(1, 126))
a.emit(movs_imm(2, 40))
a.b('h1_led_store')
a.label('h1_led_p6_idle')
a.emit(movs_imm(0, 95))
a.emit(movs_imm(1, 72))
a.emit(movs_imm(2, 0))
a.b('h1_led_store')

a.label('h1_led_pad8')         # Pad 8: THE DROP! (Fiery Orange / White Blast)
a.emit(ldrb_imm(1, 3, RS_DROP_FLASH))
a.emit(cmp_imm(1, 0))
a.b_cond('ne', 'h1_led_white')
a.emit(movs_imm(0, 124))
a.emit(movs_imm(1, 24))
a.emit(movs_imm(2, 0))
a.b('h1_led_store')

a.label('h1_led_white')
a.emit(movs_imm(0, 126))
a.emit(movs_imm(1, 126))
a.emit(movs_imm(2, 126))

a.label('h1_led_store')
a.emit(strb_imm(0, 5, 0))
a.emit(strb_imm(1, 5, 1))
a.emit(strb_imm(2, 5, 2))
a.emit(pop([4, 5], pc=True))

# Literal Pool H1
a.align4()
a.label('ph1_state');       a.u32(OTF64_STATE)
a.label('ph1_riser');       a.u32(OTF64_RISER)
a.label('ph1_arp_handler'); a.u32(0x20005944)
a.label('ph1_midi_send3');  a.u32(0x0800DCF5)
a.label('ph1_get_ch');      a.u32(0x08026041)
a.label('ph1_t_drop');      a.u32('str_t_drop')
a.label('ph1_v_drop');      a.u32('str_v_drop')

# ==============================================================================
# ISLAND H2: Bank B Pad Events & Mod Strip Manual Macro Riser
# ==============================================================================

# Helper: otf_bank_b_pad_event (r0 = pad 0..7, r1 = ev_type: 0=press, 1=release)
a.label('otf_bank_b_pad_event')
a.emit(push([4, 5, 6, 7], lr=True))
a.emit(movs_reg(4, 0))         # pad 0..7
a.emit(movs_reg(5, 1))         # ev_type
a.bl('ensure_otf_init')
a.emit(movs_reg(7, 0))         # OTF64_STATE
a.ldr_lit(6, 'ph2_riser')      # OTF64_RISER

a.emit(cmp_imm(5, 1))
a.b_cond('hi', 'h2_pad_done_trmp') # ignore aftertouch (2)

# --- Pad 1 (pad == 0): Accelerating Drum Roll (D1 Ch 10 SD+HC) ---
a.emit(cmp_imm(4, 0))
a.b_cond('ne', 'h2_chk_pad2')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h2_p1_rel')
a.emit(movs_imm(1, 1))
a.emit(strb_imm(1, 6, RS_ROLL_HELD))
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 6, RS_ROLL_TICKS))
a.emit(movs_imm(1, 11))
a.emit(strb_imm(1, 6, RS_ROLL_SUB))
a.emit(movs_imm(0, 72))
a.bl('otf_fire_d1_roll_hit')
a.ldr_lit(0, 'ph2_t_roll')
a.ldr_lit(1, 'ph2_v_roll')
a.b('h2_show_done')

a.label('h2_pad_done_trmp')
a.b('h2_pad_done')

a.label('h2_p1_rel')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 6, RS_ROLL_HELD))
a.emit(ldrb_imm(2, 6, RS_ROLL_NOTE_ON))
a.emit(cmp_imm(2, 0))
a.b_cond('eq', 'h2_pad_done_trmp')
a.emit(strb_imm(1, 6, RS_ROLL_NOTE_ON))
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 38))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 39))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.b('h2_pad_done')

# --- Pad 2 (pad == 1): 4-Bar / 8-Bar (Hold) Hands-Free Auto-Riser ---
a.label('h2_chk_pad2')
a.emit(cmp_imm(4, 1))
a.b_cond('ne', 'h2_chk_pad3')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h2_pad_done_trmp')
a.emit(ldrb_imm(1, 6, RS_AUTORISER))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h2_p2_start')
a.bl('otf_restore_original_ccs')
a.ldr_lit(0, 'ph2_t_ar4')
a.ldr_lit(1, 'ph2_v_ar_off')
a.b('h2_show_done')

a.label('h2_p2_start')
a.emit(movs_imm(1, 0))
a.emit(strh_imm(1, 6, RS_AUTORISER_POS))
a.ldr_lit(0, 'ph2_shift_obj')
a.emit(movs_imm(1, 0x15))
a.ldr_lit(3, 'ph2_check_btn')
a.emit(blx(3))
a.emit(cmp_imm(0, 0))
a.b_cond('ne', 'h2_p2_8bar')
a.emit(movs_imm(1, 1))
a.emit(strb_imm(1, 6, RS_AUTORISER))
a.ldr_lit(0, 'ph2_t_ar4')
a.ldr_lit(1, 'ph2_v_ar4_go')
a.b('h2_show_done')

a.label('h2_p2_8bar')
a.emit(ldrb_imm(1, 7, ST_MOD_USED))
a.emit(movs_imm(2, MOD_HOLD_USED))
a.emit(orrs_reg(1, 2))
a.emit(strb_imm(1, 7, ST_MOD_USED))
a.emit(movs_imm(1, 2))
a.emit(strb_imm(1, 6, RS_AUTORISER))
a.ldr_lit(0, 'ph2_t_ar8')
a.ldr_lit(1, 'ph2_v_ar8_go')
a.b('h2_show_done')

# --- Pad 3 (pad == 2): Momentary Synth Pitch Rise / Hold = Tape-Stop Dive ---
a.label('h2_chk_pad3')
a.emit(cmp_imm(4, 2))
a.b_cond('ne', 'h2_chk_pad4')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h2_p3_rel')
a.bl('otf_get_active_ch')
a.emit(strb_imm(0, 6, RS_PITCH_CH))
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 6, RS_PITCH_TICKS))
a.ldr_lit(0, 'ph2_shift_obj')
a.emit(movs_imm(1, 0x15))
a.ldr_lit(3, 'ph2_check_btn')
a.emit(blx(3))
a.emit(cmp_imm(0, 0))
a.b_cond('ne', 'h2_p3_dive')
a.emit(movs_imm(1, 1))
a.emit(strb_imm(1, 6, RS_PITCH_MODE))
a.ldr_lit(0, 'ph2_t_prise')
a.ldr_lit(1, 'ph2_v_prise')
a.b('h2_show_done')

a.label('h2_p3_dive')
a.emit(ldrb_imm(1, 7, ST_MOD_USED))
a.emit(movs_imm(2, MOD_HOLD_USED))
a.emit(orrs_reg(1, 2))
a.emit(strb_imm(1, 7, ST_MOD_USED))
a.emit(movs_imm(1, 2))
a.emit(strb_imm(1, 6, RS_PITCH_MODE))
a.ldr_lit(0, 'ph2_t_tstop')
a.ldr_lit(1, 'ph2_v_tstop')
a.b('h2_show_done')

a.label('h2_p3_rel')
a.emit(ldrb_imm(1, 6, RS_PITCH_MODE))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h2_pad_done')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 6, RS_PITCH_MODE))
a.emit(ldrb_imm(4, 6, RS_PITCH_CH))
a.emit(movs_imm(0, 0xE0))
a.emit(orrs_reg(0, 4))
a.emit(movs_imm(1, 0))
a.emit(movs_imm(2, 0x40))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0xB0))
a.emit(orrs_reg(0, 4))
a.emit(movs_imm(1, 1))
a.emit(ldrb_imm(2, 6, RS_HOME_MOD))
a.bl('otf_send_midi3')
a.b('h2_pad_done')

# --- Pad 4 (pad == 3): Momentary Pre-Drop Vacuum Gate (Mute Kill) ---
a.label('h2_chk_pad4')
a.emit(cmp_imm(4, 3))
a.b_cond('ne', 'h2_chk_pad7')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h2_p4_rel')
a.emit(movs_imm(1, 1))
a.emit(strb_imm(1, 6, RS_VACUUM_HELD))
# Cut ringing notes on SH-4d Ch 1-4, Donner B1 Ch 6, and active ch (CC123 All Notes Off)
a.emit(movs_imm(4, 0))
a.label('h2_vac_loop')
a.emit(movs_imm(0, 0xB0))
a.emit(adds_reg(0, 0, 4))
a.emit(movs_imm(1, 123))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.emit(adds_imm8(4, 1))
a.emit(cmp_imm(4, 4))
a.b_cond('lo', 'h2_vac_loop')
a.emit(movs_imm(0, 0xB5))      # Ch 6 (Donner B1)
a.emit(movs_imm(1, 123))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.ldr_lit(0, 'ph2_t_vac')
a.ldr_lit(1, 'ph2_v_vac_on')
a.b('h2_show_done')

a.label('h2_p4_rel')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 6, RS_VACUUM_HELD))
a.ldr_lit(0, 'ph2_t_vac')
a.ldr_lit(1, 'ph2_v_vac_off')
a.b('h2_show_done')

# --- Pad 7 (pad == 6): Donner D1 SMP1 Uplifter (Note 60) / Hold = SMP3 (Note 64) ---
a.label('h2_chk_pad7')
a.emit(cmp_imm(4, 6))
a.b_cond('ne', 'h2_chk_pad8')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h2_p7_rel')
a.ldr_lit(0, 'ph2_shift_obj')
a.emit(movs_imm(1, 0x15))
a.ldr_lit(3, 'ph2_check_btn')
a.emit(blx(3))
a.emit(cmp_imm(0, 0))
a.b_cond('ne', 'h2_p7_smp3')
a.emit(movs_imm(4, 60))        # SMP1 = Note 60
a.ldr_lit(5, 'ph2_v_smp1')
a.b('h2_p7_fire')
a.label('h2_p7_smp3')
a.emit(ldrb_imm(1, 7, ST_MOD_USED))
a.emit(movs_imm(2, MOD_HOLD_USED))
a.emit(orrs_reg(1, 2))
a.emit(strb_imm(1, 7, ST_MOD_USED))
a.emit(movs_imm(4, 64))        # SMP3 = Note 64
a.ldr_lit(5, 'ph2_v_smp3')
a.label('h2_p7_fire')
a.emit(strb_imm(4, 6, RS_D1_FX_NOTE))
a.emit(movs_imm(0, 0x99))
a.emit(movs_reg(1, 4))
a.emit(movs_imm(2, 122))
a.bl('otf_send_midi3')
a.ldr_lit(0, 'ph2_t_d1fx')
a.emit(movs_reg(1, 5))
a.b('h2_show_done')

a.label('h2_p7_rel')
a.emit(ldrb_imm(1, 6, RS_D1_FX_NOTE))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h2_pad_done')
a.emit(movs_imm(2, 0))
a.emit(strb_imm(2, 6, RS_D1_FX_NOTE))
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.b('h2_pad_done')

# --- Pad 8 (pad == 7): THE DROP! (Instant Snap-Back + Step 1 + D1 Crash & Impact) ---
a.label('h2_chk_pad8')
a.emit(cmp_imm(4, 7))
a.b_cond('ne', 'h2_pad_done')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h2_pad_done')
a.bl('otf_execute_drop')
a.b('h2_pad_done')

a.label('h2_show_done')
a.bl('otf_show_param')
a.label('h2_pad_done')
a.emit(pop([4, 5, 6, 7], pc=True))

# Helper: otf_handle_mod_strip (r0 = ControlHandler*, r1 = 0x2A, r2 = raw_val)
a.label('otf_handle_mod_strip')
a.emit(push([4, 5, 6, 7], lr=True))
a.emit(movs_reg(4, 0))
a.emit(movs_reg(5, 1))
a.emit(movs_reg(6, 2))

a.ldr_lit(2, 'ph2_arp_params')
a.emit(ldrh_imm(2, 2, 2))
a.emit(cmp_imm(2, 5))
a.b_cond('ne', 'h2_mod_pass')

a.bl('ensure_otf_init')
a.emit(movs_reg(7, 0))         # OTF64_STATE

a.ldr_lit(0, 'ph2_work_mem')
a.emit(movs_imm(1, 3))
a.ldr_lit(3, 'ph2_get_mode')
a.emit(blx(3))
a.emit(cmp_imm(0, 1))          # Pad Bank B == 1?
a.b_cond('eq', 'h2_mod_riser')

# In Bank A: remember Mod Strip position as RS_HOME_MOD and pass through normally!
a.emit(asrs_imm(1, 6, 7))
a.emit(movs_imm(2, 0x7F))
a.emit(ands_reg(1, 2))
a.ldr_lit(2, 'ph2_riser')
a.emit(strb_imm(1, 2, RS_HOME_MOD))

a.label('h2_mod_pass')
a.emit(movs_reg(0, 4))
a.emit(movs_reg(1, 5))
a.emit(movs_reg(2, 6))
a.ldr_lit(3, 'ph2_orig_ctrl')
a.emit(blx(3))
a.emit(pop([4, 5, 6, 7], pc=True))

a.label('h2_mod_riser')
a.emit(asrs_imm(4, 6, 7))
a.emit(movs_imm(2, 0x7F))
a.emit(ands_reg(4, 2))         # r4 = val (0..127)
a.ldr_lit(5, 'ph2_riser')
a.emit(ldrb_imm(1, 5, RS_MANUAL_RISER))
a.emit(cmp_reg(4, 1))
a.b_cond('eq', 'h2_mod_ret1')
a.emit(strb_imm(4, 5, RS_MANUAL_RISER))

# Format "Manual Riser" / "Tension: XX%"
a.emit(movs_imm(1, 100))
a.emit(muls_reg(4, 1))
a.emit(adds_imm8(4, 63))
a.emit(lsrs_imm(4, 4, 7))      # r4 = 0..100%
a.emit(adds_imm8(7, ST_VAL_BUF))
a.emit(movs_reg(0, 7))
a.ldr_lit(1, 'ph2_pfx_ten')
a.bl('otf_fmt_cstr')
a.emit(movs_reg(1, 4))
a.bl('otf_fmt_u8')
a.emit(movs_imm(2, 0x25))      # '%'
a.emit(strb_imm(2, 0, 0))
a.emit(movs_imm(2, 0))
a.emit(strb_imm(2, 0, 1))
a.ldr_lit(0, 'ph2_t_mriser')
a.emit(movs_reg(1, 7))
a.bl('otf_show_param')

a.label('h2_mod_ret1')
a.emit(movs_imm(0, 1))
a.emit(pop([4, 5, 6, 7], pc=True))

# Literal Pool H2
a.align4()
a.label('ph2_riser');       a.u32(OTF64_RISER)
a.label('ph2_orig_ctrl');   a.u32(0x08023719)
a.label('ph2_arp_params');  a.u32(0x2000122A)
a.label('ph2_work_mem');    a.u32(0x20000EB8)
a.label('ph2_get_mode');    a.u32(0x0800CE15)
a.label('ph2_shift_obj');   a.u32(0x20000B5C)
a.label('ph2_check_btn');   a.u32(0x0800A7B9)
a.label('ph2_t_roll');      a.u32('str_t_roll')
a.label('ph2_v_roll');      a.u32('str_v_roll')
a.label('ph2_t_ar4');       a.u32('str_t_ar4')
a.label('ph2_t_ar8');       a.u32('str_t_ar8')
a.label('ph2_v_ar_off');    a.u32('str_v_ar_off')
a.label('ph2_v_ar4_go');    a.u32('str_v_ar4_go')
a.label('ph2_v_ar8_go');    a.u32('str_v_ar8_go')
a.label('ph2_t_prise');     a.u32('str_t_prise')
a.label('ph2_v_prise');     a.u32('str_v_prise')
a.label('ph2_t_tstop');     a.u32('str_t_tstop')
a.label('ph2_v_tstop');     a.u32('str_v_tstop')
a.label('ph2_t_vac');       a.u32('str_t_vac')
a.label('ph2_v_vac_on');    a.u32('str_v_vac_on')
a.label('ph2_v_vac_off');   a.u32('str_v_vac_off')
a.label('ph2_t_d1fx');      a.u32('str_t_d1fx')
a.label('ph2_v_smp1');      a.u32('str_v_smp1')
a.label('ph2_v_smp3');      a.u32('str_v_smp3')
a.label('ph2_t_mriser');    a.u32('str_t_mriser')
a.label('ph2_pfx_ten');     a.u32('pfx_tension')

# ==============================================================================
# ISLAND H3: 24 PPQN Riser, Auto-Drop Countdown, Roll & Pitch Sweep Engine
# ==============================================================================

a.label('otf_riser_sync_start')
a.emit(push([4], lr=True))
a.ldr_lit(4, 'ph3_riser')
a.bl('otf_get_micros')
a.emit(str_imm(0, 4, RS_LAST_US))
a.emit(movs_imm(1, 0))
a.emit(str_imm(1, 4, RS_PHASE_ACC))
a.emit(strb_imm(1, 4, RS_BEAT_BLINK))
a.emit(pop([4], pc=True))

a.label('otf_riser_on_stop')
a.emit(push([4], lr=True))
a.ldr_lit(4, 'ph3_riser')
a.emit(ldrb_imm(1, 4, RS_AUTORISER))
a.emit(ldrb_imm(2, 4, RS_ROLL_HELD))
a.emit(orrs_reg(1, 2))
a.emit(ldrb_imm(2, 4, RS_MANUAL_RISER))
a.emit(orrs_reg(1, 2))
a.emit(ldrb_imm(2, 4, RS_PITCH_MODE))
a.emit(orrs_reg(1, 2))
a.emit(ldrb_imm(2, 4, RS_VACUUM_HELD))
a.emit(orrs_reg(1, 2))
a.b_cond('eq', 'h3_stop_done')
a.bl('otf_restore_original_ccs')
a.label('h3_stop_done')
a.emit(pop([4], pc=True))

# Called once per 24 PPQN tick
a.label('otf_riser_on_24ppqn')
a.emit(push([4, 5, 6, 7], lr=True))
a.emit(sub_sp(12))             # 20 + 12 = 32B frame (strict 8-byte AAPCS alignment!)
a.ldr_lit(4, 'ph3_riser')

# 1. Clean NoteOff for previous tick's D1 Snare/Clap roll hit
a.emit(ldrb_imm(1, 4, RS_ROLL_NOTE_ON))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_chk_drop_off')
a.emit(movs_imm(1, 0))
a.emit(strb_imm(1, 4, RS_ROLL_NOTE_ON))
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 38))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 39))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.emit(ldrb_imm(1, 4, RS_ROLL_HELD))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_chk_drop_off')
a.bl('otf_refresh_pads')

# 2. Clean NoteOff countdown for Drop Crash (49) + SMP2 Impact (62)
a.label('h3_chk_drop_off')
a.emit(ldrb_imm(1, 4, RS_DROP_OFF_CNT))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_chk_flash')
a.emit(subs_imm8(1, 1))
a.emit(strb_imm(1, 4, RS_DROP_OFF_CNT))
a.b_cond('ne', 'h3_chk_flash')
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 49))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')
a.emit(movs_imm(0, 0x89))
a.emit(movs_imm(1, 62))
a.emit(movs_imm(2, 0))
a.bl('otf_send_midi3')

# 3. Pad 8 Drop White Flash countdown
a.label('h3_chk_flash')
a.emit(ldrb_imm(1, 4, RS_DROP_FLASH))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_beat_blink')
a.emit(subs_imm8(1, 1))
a.emit(strb_imm(1, 4, RS_DROP_FLASH))
a.b_cond('ne', 'h3_beat_blink')
a.bl('otf_refresh_pads')

# 4. Quarter-note Beat Blink (0..23)
a.label('h3_beat_blink')
a.emit(ldrb_imm(1, 4, RS_BEAT_BLINK))
a.emit(adds_imm8(1, 1))
a.emit(cmp_imm(1, 24))
a.b_cond('lo', 'h3_bb_save')
a.emit(movs_imm(1, 0))
a.label('h3_bb_save')
a.emit(strb_imm(1, 4, RS_BEAT_BLINK))

# 5. Auto-Riser (4-Bar = 384 ticks, 8-Bar = 768 ticks)
a.emit(movs_imm(5, 0))         # r5 = auto_tension (0..127)
a.emit(ldrb_imm(6, 4, RS_AUTORISER))
a.emit(cmp_imm(6, 0))
a.b_cond('eq', 'h3_apply_ten')

a.emit(ldrb_imm(1, 4, RS_BEAT_BLINK))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_ar_pulse')
a.emit(cmp_imm(1, 6))
a.b_cond('ne', 'h3_ar_step')
a.label('h3_ar_pulse')
a.bl('otf_refresh_pads')

a.label('h3_ar_step')
a.emit(movs_imm(7, 192))
a.emit(lsls_imm(7, 7, 1))      # r7 = 384
a.emit(cmp_imm(6, 1))
a.b_cond('eq', 'h3_ar_got_tot')
a.emit(lsls_imm(7, 7, 1))      # r7 = 768
a.label('h3_ar_got_tot')
a.emit(ldrh_imm(0, 4, RS_AUTORISER_POS))
a.emit(adds_imm8(0, 1))
a.emit(cmp_reg(0, 7))
a.b_cond('lo', 'h3_ar_cont')
# Beat 1.1 Reached -> AUTO-DROP!
a.bl('otf_execute_drop')
a.emit(add_sp(12))
a.emit(pop([4, 5, 6, 7], pc=True))

a.label('h3_ar_cont')
a.emit(strh_imm(0, 4, RS_AUTORISER_POS))
a.emit(subs_reg(7, 7, 0))      # r7 = rem (1..767)
a.emit(cmp_imm(6, 1))
a.b_cond('eq', 'h3_ar_t4')
a.emit(lsrs_imm(0, 0, 1))
a.label('h3_ar_t4')
a.emit(movs_imm(1, 85))
a.emit(muls_reg(0, 1))
a.emit(lsrs_imm(5, 0, 8))      # r5 = auto_tension 0..127!

# Divide rem (r7) by 24 -> r0 = rem % 24, r1 = rem // 24
a.emit(movs_reg(0, 7))
a.emit(movs_imm(1, 0))
a.label('h3_div24')
a.emit(cmp_imm(0, 24))
a.b_cond('lo', 'h3_div24_done')
a.emit(subs_imm8(0, 24))
a.emit(adds_imm8(1, 1))
a.b('h3_div24')
a.label('h3_div24_done')
a.emit(str_sp(0, 0))           # [sp+0] = rem % 24

# Update OLED Beat Countdown ("DROP IN: B.b") whenever rem % 24 == 0!
a.emit(cmp_imm(0, 0))
a.b_cond('ne', 'h3_ar_chk_roll')
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_ar_chk_roll')
a.emit(subs_imm8(1, 1))        # b_idx = (rem // 24) - 1
a.emit(lsrs_imm(2, 1, 2))
a.emit(adds_imm8(2, 0x31))     # '1' + bar_idx ('1'..'8')
a.emit(movs_imm(3, 3))
a.emit(ands_reg(1, 3))
a.emit(adds_imm8(1, 0x31))     # '1' + beat_idx ('1'..'4')
a.emit(str_sp(1, 4))
a.emit(str_sp(2, 8))
a.ldr_lit(0, 'ph3_state')
a.emit(adds_imm8(0, ST_VAL_BUF))
a.ldr_lit(1, 'ph3_pfx_dropin')
a.bl('otf_fmt_cstr')
a.emit(ldr_sp(2, 8))           # Bar digit
a.emit(ldr_sp(1, 4))           # Beat digit
a.emit(strb_imm(2, 0, 0))
a.emit(movs_imm(2, 0x2E))      # '.'
a.emit(strb_imm(2, 0, 1))
a.emit(strb_imm(1, 0, 2))
a.emit(movs_imm(2, 0))
a.emit(strb_imm(2, 0, 3))
a.ldr_lit(1, 'ph3_state')
a.emit(adds_imm8(1, ST_VAL_BUF))
a.ldr_lit(0, 'ph3_t_ar4')
a.emit(cmp_imm(6, 1))
a.b_cond('eq', 'h3_ar_show_cd')
a.ldr_lit(0, 'ph3_t_ar8')
a.label('h3_ar_show_cd')
a.bl('otf_show_param')

# Final-Bar Auto Snare Roll (6 < rem <= 96) if Pad 1 not manually held
a.label('h3_ar_chk_roll')
a.emit(ldr_sp(0, 0))           # r0 = rem % 24 (0..23)
a.emit(ldrb_imm(1, 4, RS_ROLL_HELD))
a.emit(cmp_imm(1, 0))
a.b_cond('ne', 'h3_apply_ten')
a.emit(cmp_imm(7, 96))
a.b_cond('hi', 'h3_apply_ten')
a.emit(cmp_imm(7, 6))
a.b_cond('ls', 'h3_apply_ten')

a.emit(cmp_imm(7, 48))
a.b_cond('ls', 'h3_ar_r32')
# 48 < rem <= 96 -> 1/16th Snare (r0 in {0, 6, 12, 18})
a.label('h3_mod6')
a.emit(cmp_imm(0, 6))
a.b_cond('lo', 'h3_mod6_done')
a.emit(subs_imm8(0, 6))
a.b('h3_mod6')
a.label('h3_mod6_done')
a.emit(cmp_imm(0, 0))
a.b_cond('ne', 'h3_apply_ten')
a.emit(movs_imm(0, 86))
a.bl('otf_fire_d1_roll_hit')
a.b('h3_apply_ten')

a.label('h3_ar_r32')
a.emit(cmp_imm(7, 24))
a.b_cond('ls', 'h3_ar_r64')
# 24 < rem <= 48 -> 1/32nd Snare+Clap (r0 % 3 == 0)
a.label('h3_mod3')
a.emit(cmp_imm(0, 3))
a.b_cond('lo', 'h3_mod3_done')
a.emit(subs_imm8(0, 3))
a.b('h3_mod3')
a.label('h3_mod3_done')
a.emit(cmp_imm(0, 0))
a.b_cond('ne', 'h3_apply_ten')
a.emit(movs_imm(0, 108))
a.bl('otf_fire_d1_roll_hit')
a.b('h3_apply_ten')

a.label('h3_ar_r64')
# 6 < rem <= 24 -> 1/64th Buzz Roll (r0 % 2 == 0)
a.emit(movs_imm(1, 1))
a.emit(tst_reg(0, 1))
a.b_cond('ne', 'h3_apply_ten')
a.emit(movs_imm(0, 124))
a.bl('otf_fire_d1_roll_hit')

# 6. Apply Combined Tension = max(auto_tension, RS_MANUAL_RISER)
a.label('h3_apply_ten')
a.emit(ldrb_imm(1, 4, RS_MANUAL_RISER))
a.emit(cmp_reg(1, 5))
a.b_cond('ls', 'h3_got_max_ten')
a.emit(movs_reg(5, 1))
a.label('h3_got_max_ten')
a.emit(cmp_imm(5, 0))
a.b_cond('ne', 'h3_do_ten')
a.emit(ldrb_imm(2, 4, RS_LAST_TENSION))
a.emit(cmp_imm(2, 0xFF))
a.b_cond('eq', 'h3_chk_man_roll')
a.emit(cmp_imm(2, 0))
a.b_cond('eq', 'h3_chk_man_roll')
a.label('h3_do_ten')
a.emit(movs_reg(0, 5))
a.bl('otf_apply_riser_tension')

# 7. Manual Pad 1 Accelerating Drum Roll
a.label('h3_chk_man_roll')
a.emit(ldrb_imm(1, 4, RS_ROLL_HELD))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_chk_pitch')
a.emit(ldrb_imm(2, 4, RS_ROLL_TICKS))
a.emit(cmp_imm(2, 200))
a.b_cond('hs', 'h3_rt_max')
a.emit(adds_imm8(2, 1))
a.emit(strb_imm(2, 4, RS_ROLL_TICKS))
a.label('h3_rt_max')
a.emit(ldrb_imm(3, 4, RS_MANUAL_RISER))
a.emit(cmp_reg(3, 2))
a.b_cond('ls', 'h3_rt_eff')
a.emit(movs_reg(2, 3))
a.label('h3_rt_eff')
a.emit(ldrb_imm(1, 4, RS_ROLL_SUB))
a.emit(cmp_imm(1, 0))
a.b_cond('eq', 'h3_roll_fire')
a.emit(subs_imm8(1, 1))
a.emit(strb_imm(1, 4, RS_ROLL_SUB))
a.b('h3_chk_pitch')

a.label('h3_roll_fire')
a.emit(cmp_imm(2, 24))
a.b_cond('hs', 'h3_rf_16')
a.emit(movs_imm(5, 11))        # 1/8th (period 12)
a.emit(movs_imm(0, 68))
a.b('h3_rf_go')
a.label('h3_rf_16')
a.emit(cmp_imm(2, 48))
a.b_cond('hs', 'h3_rf_32')
a.emit(movs_imm(5, 5))         # 1/16th (period 6)
a.emit(movs_imm(0, 88))
a.b('h3_rf_go')
a.label('h3_rf_32')
a.emit(cmp_imm(2, 72))
a.b_cond('hs', 'h3_rf_64')
a.emit(movs_imm(5, 2))         # 1/32nd (period 3)
a.emit(movs_imm(0, 108))
a.b('h3_rf_go')
a.label('h3_rf_64')
a.emit(movs_imm(5, 1))         # 1/64th buzz (period 2)
a.emit(movs_imm(0, 125))
a.label('h3_rf_go')
a.emit(strb_imm(5, 4, RS_ROLL_SUB))
a.bl('otf_fire_d1_roll_hit')
a.bl('otf_refresh_pads')

# 8. Pad 3 Synth Pitch Rise UP (mode 1) / Tape-Stop DIVE (mode 2)
a.label('h3_chk_pitch')
a.emit(ldrb_imm(5, 4, RS_PITCH_MODE))
a.emit(cmp_imm(5, 0))
a.b_cond('eq', 'h3_done')
a.emit(ldrb_imm(6, 4, RS_PITCH_TICKS))
a.emit(cmp_imm(6, 96))
a.b_cond('hs', 'h3_pt_clamped')
a.emit(adds_imm8(6, 1))
a.emit(strb_imm(6, 4, RS_PITCH_TICKS))
a.label('h3_pt_clamped')
a.emit(ldrb_imm(7, 4, RS_PITCH_CH))

a.emit(cmp_imm(5, 1))
a.b_cond('ne', 'h3_pitch_dive')
# Mode 1: Pitch Bend 8192 + t*85 (0..+8160) + CC1 ramp
a.emit(movs_reg(3, 6))
a.emit(movs_imm(1, 85))
a.emit(muls_reg(3, 1))         # 0..8160
a.emit(movs_imm(2, 0x80))
a.emit(lsls_imm(2, 2, 6))      # 8192
a.emit(adds_reg(2, 2, 3))      # pb14 = 8192..16352
a.emit(movs_imm(0, 0xE0))
a.emit(orrs_reg(0, 7))
a.emit(movs_reg(1, 2))
a.emit(movs_imm(5, 0x7F))
a.emit(ands_reg(1, 5))         # LSB
a.emit(lsrs_imm(2, 2, 7))
a.emit(ands_reg(2, 5))         # MSB
a.emit(str_sp(3, 0))
a.bl('otf_send_midi3')
a.emit(ldr_sp(3, 0))
a.emit(lsrs_imm(2, 3, 6))      # 0..127 CC1 mod
a.emit(ldrb_imm(1, 4, RS_HOME_MOD))
a.emit(cmp_reg(2, 1))
a.b_cond('hs', 'h3_mod_ok')
a.emit(movs_reg(2, 1))
a.label('h3_mod_ok')
a.emit(movs_imm(0, 0xB0))
a.emit(orrs_reg(0, 7))
a.emit(movs_imm(1, 1))
a.bl('otf_send_midi3')
a.b('h3_done')

a.label('h3_pitch_dive')
a.emit(cmp_imm(6, 36))
a.b_cond('ls', 'h3_pd_ok')
a.emit(movs_imm(6, 36))
a.label('h3_pd_ok')
a.emit(movs_imm(1, 227))
a.emit(muls_reg(6, 1))         # 0..8172
a.emit(movs_imm(2, 0x80))
a.emit(lsls_imm(2, 2, 6))      # 8192
a.emit(subs_reg(2, 2, 6))      # pb14 = 8192..20
a.emit(movs_imm(0, 0xE0))
a.emit(orrs_reg(0, 7))
a.emit(movs_reg(1, 2))
a.emit(movs_imm(5, 0x7F))
a.emit(ands_reg(1, 5))
a.emit(lsrs_imm(2, 2, 7))
a.emit(ands_reg(2, 5))
a.bl('otf_send_midi3')

a.label('h3_done')
a.emit(add_sp(12))
a.emit(pop([4, 5, 6, 7], pc=True))

# Main-loop 24 PPQN Poller for Riser & Drop Engine (works with or without Pad 6 Start!)
a.label('otf_riser_tick_poll')
a.emit(push([4, 5, 6], lr=True))
a.ldr_lit(4, 'ph3_riser')
a.bl('otf_get_micros')
a.emit(ldr_imm(5, 4, RS_LAST_US))
a.emit(str_imm(0, 4, RS_LAST_US))
a.emit(cmp_imm(5, 0))
a.b_cond('eq', 'h3_poll_exit')

a.emit(subs_reg(5, 0, 5))
a.ldr_lit(3, 'ph3_max_dt_us')
a.emit(cmp_reg(5, 3))
a.b_cond('ls', 'h3_dt_ok')
a.emit(movs_reg(5, 3))
a.label('h3_dt_ok')

a.ldr_lit(2, 'ph3_centi_bpm')
a.emit(ldrh_imm(1, 2, 0))
a.ldr_lit(3, 'ph3_min_cbpm')
a.emit(cmp_reg(1, 3))
a.b_cond('hs', 'h3_cb_min_ok')
a.ldr_lit(1, 'ph3_def_cbpm')
a.label('h3_cb_min_ok')
a.ldr_lit(3, 'ph3_max_cbpm')
a.emit(cmp_reg(1, 3))
a.b_cond('ls', 'h3_cb_max_ok')
a.emit(movs_reg(1, 3))
a.label('h3_cb_max_ok')

a.emit(muls_reg(5, 1))
a.emit(ldr_imm(6, 4, RS_PHASE_ACC))
a.emit(adds_reg(6, 6, 5))

a.label('h3_poll_loop')
a.ldr_lit(3, 'ph3_f8_thresh')
a.emit(cmp_reg(6, 3))
a.b_cond('lo', 'h3_poll_save')
a.emit(subs_reg(6, 6, 3))
a.emit(str_imm(6, 4, RS_PHASE_ACC))
a.bl('otf_riser_on_24ppqn')
a.ldr_lit(4, 'ph3_riser')
a.emit(ldr_imm(6, 4, RS_PHASE_ACC)) # reload in case Auto-Drop zeroed RS_PHASE_ACC!
a.b('h3_poll_loop')

a.label('h3_poll_save')
a.emit(str_imm(6, 4, RS_PHASE_ACC))
a.label('h3_poll_exit')
a.emit(pop([4, 5, 6], pc=True))

