def pad16(s):
    b = s.encode('ascii') + b'\x00'
    assert len(b) <= 16, f"String too long ({len(b)}): {s}"
    return b + b'\x00' * (16 - len(b))

def cstr(s):
    return s.encode('ascii') + b'\x00'

